BEGIN
  CREATE TEMP TABLE _u ON COMMIT DROP AS
  SELECT DISTINCT p.user_id FROM public.profiles p
  WHERE regexp_replace(p.cpf,'[^0-9]','','g') = ANY(v_cpfs);

  INSERT INTO public.enrollments (user_id, course_id, progress, status)
  SELECT u.user_id, v_course, 100, 'concluido' FROM _u u
  ON CONFLICT (user_id, course_id) DO UPDATE SET progress = 100, status = 'concluido', updated_at = now();

  INSERT INTO public.lesson_completions (user_id, lesson_id)
  SELECT u.user_id, l.id
  FROM _u u
  CROSS JOIN (
    SELECT l.id FROM public.course_lessons l
    JOIN public.course_modules m ON m.id = l.module_id
    WHERE m.course_id = v_course
  ) l
  ON CONFLICT (user_id, lesson_id) DO NOTHING;
END $$;